func (mmSubscribe *mUserRepositoryMockSubscribe) When(ctx context.Context, req *repoModels.SubscribeRequest) *UserRepositoryMockSubscribeExpectation {
	if mmSubscribe.mock.funcSubscribe != nil {
		mmSubscribe.mock.t.Fatalf("UserRepositoryMock.Subscribe mock is already set by Set")
	}

	expectation := &UserRepositoryMockSubscribeExpectation{
		mock:               mmSubscribe.mock,
		params:             &UserRepositoryMockSubscribeParams{ctx, req},
		expectationOrigins: UserRepositoryMockSubscribeExpectationOrigins{origin: minimock.CallerInfo(1)},
	}
	mmSubscribe.expectations = append(mmSubscribe.expectations, expectation)
	return expectation
}

// Then sets up UserRepository.Subscribe return parameters for the expectation previously defined by the When method
func (e *UserRepositoryMockSubscribeExpectation) Then(err error) *UserRepositoryMock {
	e.results = &UserRepositoryMockSubscribeResults{err}
	return e.mock
}

// Times sets number of times UserRepository.Subscribe should be invoked
func (mmSubscribe *mUserRepositoryMockSubscribe) Times(n uint64) *mUserRepositoryMockSubscribe {
	if n == 0 {
		mmSubscribe.mock.t.Fatalf("Times of UserRepositoryMock.Subscribe mock can not be zero")
	}
	mm_atomic.StoreUint64(&mmSubscribe.expectedInvocations, n)
	mmSubscribe.expectedInvocationsOrigin = minimock.CallerInfo(1)
	return mmSubscribe
}

func (mmSubscribe *mUserRepositoryMockSubscribe) invocationsDone() bool {
	if len(mmSubscribe.expectations) == 0 && mmSubscribe.defaultExpectation == nil && mmSubscribe.mock.funcSubscribe == nil {
		return true
	}

	totalInvocations := mm_atomic.LoadUint64(&mmSubscribe.mock.afterSubscribeCounter)
	expectedInvocations := mm_atomic.LoadUint64(&mmSubscribe.expectedInvocations)

	return totalInvocations > 0 && (expectedInvocations == 0 || expectedInvocations == totalInvocations)
}

// Subscribe implements mm_repository.UserRepository
func (mmSubscribe *UserRepositoryMock) Subscribe(ctx context.Context, req *repoModels.SubscribeRequest) (err error) {
	mm_atomic.AddUint64(&mmSubscribe.beforeSubscribeCounter, 1)
	defer mm_atomic.AddUint64(&mmSubscribe.afterSubscribeCounter, 1)

	mmSubscribe.t.Helper()

	if mmSubscribe.inspectFuncSubscribe != nil {
		mmSubscribe.inspectFuncSubscribe(ctx, req)
	}

	mm_params := UserRepositoryMockSubscribeParams{ctx, req}

	// Record call args
	mmSubscribe.SubscribeMock.mutex.Lock()
	mmSubscribe.SubscribeMock.callArgs = append(mmSubscribe.SubscribeMock.callArgs, &mm_params)
	mmSubscribe.SubscribeMock.mutex.Unlock()

	for _, e := range mmSubscribe.SubscribeMock.expectations {
		if minimock.Equal(*e.params, mm_params) {
			mm_atomic.AddUint64(&e.Counter, 1)
			return e.results.err
		}
	}

	if mmSubscribe.SubscribeMock.defaultExpectation != nil {
		mm_atomic.AddUint64(&mmSubscribe.SubscribeMock.defaultExpectation.Counter, 1)
		mm_want := mmSubscribe.SubscribeMock.defaultExpectation.params
		mm_want_ptrs := mmSubscribe.SubscribeMock.defaultExpectation.paramPtrs

		mm_got := UserRepositoryMockSubscribeParams{ctx, req}

		if mm_want_ptrs != nil {

			if mm_want_ptrs.ctx != nil && !minimock.Equal(*mm_want_ptrs.ctx, mm_got.ctx) {
				mmSubscribe.t.Errorf("UserRepositoryMock.Subscribe got unexpected parameter ctx, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmSubscribe.SubscribeMock.defaultExpectation.expectationOrigins.originCtx, *mm_want_ptrs.ctx, mm_got.ctx, minimock.Diff(*mm_want_ptrs.ctx, mm_got.ctx))
			}

			if mm_want_ptrs.req != nil && !minimock.Equal(*mm_want_ptrs.req, mm_got.req) {
				mmSubscribe.t.Errorf("UserRepositoryMock.Subscribe got unexpected parameter req, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
					mmSubscribe.SubscribeMock.defaultExpectation.expectationOrigins.originReq, *mm_want_ptrs.req, mm_got.req, minimock.Diff(*mm_want_ptrs.req, mm_got.req))
			}

		} else if mm_want != nil && !minimock.Equal(*mm_want, mm_got) {
			mmSubscribe.t.Errorf("UserRepositoryMock.Subscribe got unexpected parameters, expected at\n%s:\nwant: %#v\n got: %#v%s\n",
				mmSubscribe.SubscribeMock.defaultExpectation.expectationOrigins.origin, *mm_want, mm_got, minimock.Diff(*mm_want, mm_got))
		}

		mm_results := mmSubscribe.SubscribeMock.defaultExpectation.results
		if mm_results == nil {
			mmSubscribe.t.Fatal("No results are set for the UserRepositoryMock.Subscribe")
		}
		return (*mm_results).err
	}
	if mmSubscribe.funcSubscribe != nil {
		return mmSubscribe.funcSubscribe(ctx, req)
	}
	mmSubscribe.t.Fatalf("Unexpected call to UserRepositoryMock.Subscribe. %v %v", ctx, req)
	return
}

// SubscribeAfterCounter returns a count of finished UserRepositoryMock.Subscribe invocations
func (mmSubscribe *UserRepositoryMock) SubscribeAfterCounter() uint64 {
	return mm_atomic.LoadUint64(&mmSubscribe.afterSubscribeCounter)
}

// SubscribeBeforeCounter returns a count of UserRepositoryMock.Subscribe invocations
func (mmSubscribe *UserRepositoryMock) SubscribeBeforeCounter() uint64 {
	return mm_atomic.LoadUint64(&mmSubscribe.beforeSubscribeCounter)
}

// Calls returns a list of arguments used in each call to UserRepositoryMock.Subscribe.
// The list is in the same order as the calls were made (i.e. recent calls have a higher index)
func (mmSubscribe *mUserRepositoryMockSubscribe) Calls() []*UserRepositoryMockSubscribeParams {
	mmSubscribe.mutex.RLock()

	argCopy := make([]*UserRepositoryMockSubscribeParams, len(mmSubscribe.callArgs))
	copy(argCopy, mmSubscribe.callArgs)

	mmSubscribe.mutex.RUnlock()

	return argCopy
}

// MinimockSubscribeDone returns true if the count of the Subscribe invocations corresponds
// the number of defined expectations
func (m *UserRepositoryMock) MinimockSubscribeDone() bool {
	if m.SubscribeMock.optional {
		// Optional methods provide '0 or more' call count restriction.
		return true
	}

	for _, e := range m.SubscribeMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			return false
		}
	}

	return m.SubscribeMock.invocationsDone()
}

// MinimockSubscribeInspect logs each unmet expectation
func (m *UserRepositoryMock) MinimockSubscribeInspect() {
	for _, e := range m.SubscribeMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to UserRepositoryMock.Subscribe at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterSubscribeCounter := mm_atomic.LoadUint64(&m.afterSubscribeCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.SubscribeMock.defaultExpectation != nil && afterSubscribeCounter < 1 {
		if m.SubscribeMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to UserRepositoryMock.Subscribe at\n%s", m.SubscribeMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to UserRepositoryMock.Subscribe at\n%s with params: %#v", m.SubscribeMock.defaultExpectation.expectationOrigins.origin, *m.SubscribeMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcSubscribe != nil && afterSubscribeCounter < 1 {
		m.t.Errorf("Expected call to UserRepositoryMock.Subscribe at\n%s", m.funcSubscribeOrigin)
	}

	if !m.SubscribeMock.invocationsDone() && afterSubscribeCounter > 0 {
		m.t.Errorf("Expected %d calls to UserRepositoryMock.Subscribe at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.SubscribeMock.expectedInvocations), m.SubscribeMock.expectedInvocationsOrigin, afterSubscribeCounter)
	}
}

// MinimockFinish checks that all mocked methods have been called the expected number of times
func (m *UserRepositoryMock) MinimockFinish() {
	m.finishOnce.Do(func() {
		if !m.minimockDone() {
			m.MinimockAcceptedSubInspect()

			m.MinimockCreateUserInspect()

			m.MinimockGetSubFromInspect()

			m.MinimockGetSubIsAcceptedInspect()

			m.MinimockGetSubToInspect()

			m.MinimockGetUserInspect()

			m.MinimockSubscribeInspect()
		}
	})
}

// MinimockWait waits for all mocked methods to be called the expected number of times
func (m *UserRepositoryMock) MinimockWait(timeout mm_time.Duration) {
	timeoutCh := mm_time.After(timeout)
	for {
		if m.minimockDone() {
			return
		}
		select {
		case <-timeoutCh:
			m.MinimockFinish()
			return
		case <-mm_time.After(10 * mm_time.Millisecond):
		}
	}
}

func (m *UserRepositoryMock) minimockDone() bool {
	done := true
	return done &&
		m.MinimockAcceptedSubDone() &&
		m.MinimockCreateUserDone() &&
		m.MinimockGetSubFromDone() &&
		m.MinimockGetSubIsAcceptedDone() &&
		m.MinimockGetSubToDone() &&
		m.MinimockGetUserDone() &&
		m.MinimockSubscribeDone()
}
